    var M = {"john":{"id":"\"Yahweh Maha Pengasih\""},"mary":{"id":"Tidak pasti — \"yang dikasihi\", \"kepahitan\", atau \"anak yang didambakan\""},"muhammad":{"id":"\"Yang terpuji\", \"layak dipuji\""},"alexander":{"id":"\"Pelindung manusia\" (aléxō \"melindungi\" + anḗr \"manusia\")"},"joseph":{"id":"\"Ia akan menambah\" / \"kiranya Tuhan menambah\""},"michael":{"id":"\"Siapa yang seperti Allah?\""},"george":{"id":"\"Petani, penggarap tanah\" (gē \"bumi\" + ergon \"kerja\")"},"sophia":{"id":"\"Kebijaksanaan\""},"fatima":{"id":"\"Yang menyapih / menahan diri\" (akar kata f-ṭ-m)"},"ali":{"id":"\"Tinggi, mulia, luhur\" (akar kata ʿ-l-w)"},"krishna":{"id":"\"Gelap, hitam\" (merujuk kulit biru kehitaman sang dewa)"},"rama":{"id":"\"Menyenangkan, memikat, menggembirakan\" (akar kata ram- \"menyenangkan\")"},"david":{"id":"\"Yang dikasihi\""},"daniel":{"id":"\"Tuhan adalah hakimku\" (dān \"menghakimi\" + ʼēl \"Tuhan\")"},"peter":{"id":"\"Batu karang, batu\" — diciptakan Yesus untuk mengalihkan kata Aram Kēfā"},"paul":{"id":"\"Kecil, rendah hati\""},"thomas":{"id":"\"Kembar\""},"abraham":{"id":"“Bapak banyak bangsa”"},"isaac":{"id":"“Ia tertawa” / “ia akan tertawa”"},"jacob":{"id":"“Penyerobot”, “pemegang tumit”"},"moses":{"id":"“Yang ditarik dari air” (menurut tradisi)"},"solomon":{"id":"“Damai” (dari shalom)"},"matthew":{"id":"“Anugerah Yahweh”"},"adam":{"id":"“Manusia; umat manusia”, dari adamah “tanah, bumi”"},"noah":{"id":"“Istirahat, penghiburan”"},"gabriel":{"id":"“Allah adalah kekuatanku”"},"elijah":{"id":"“Tuhanku adalah Yahweh”"},"sarah":{"id":"“Putri, wanita bangsawan”"},"anna":{"id":"“Rahmat, karunia”"},"elizabeth":{"id":"“Allahku adalah sumpah”"},"omar":{"id":"“Panjang umur, makmur, sejahtera”"},"aisha":{"id":"“Hidup, penuh kehidupan, makmur”"},"khadija":{"id":"“Lahir dini, anak yang lahir prematur”"},"abdullah":{"id":"“Hamba Allah”"},"hassan":{"id":"\"Baik, tampan, indah\""},"husayn":{"id":"\"Hasan kecil\", \"si mungil nan rupawan\""},"zaynab":{"id":"Tumbuhan gurun berbunga yang harum"},"nicholas":{"id":"\"Kemenangan rakyat\""},"helen":{"id":"Tidak pasti — mungkin \"obor, sang cemerlang\""},"catherine":{"id":"Tidak pasti — menurut etimologi rakyat dikaitkan dengan \"suci\""},"margaret":{"id":"\"Mutiara\""},"philip":{"id":"\"Pecinta kuda\""},"theodore":{"id":"\"Anugerah Tuhan\""},"anthony":{"id":"Nama marga Romawi yang asal-usulnya tak pasti, mungkin dari Etruska"},"julia":{"id":"\"Belia\"; bentuk feminin dari nama marga Iulius, terkait dengan Jupiter"},"lakshmi":{"id":"\"Tanda, pertanda\" → \"keberuntungan, kemakmuran\""},"arjun":{"id":"\"Terang, putih, keperakan, jernih\""},"sita":{"id":"\"Alur bajak\" (garis yang digurat bajak)"},"ganesh":{"id":"\"Penguasa para gana (rombongan, bala tentara)\""},"priya":{"id":"\"Terkasih, tersayang\""}};
    var B = {"john":{"id":"Salah satu nama yang paling tersebar luas di Bumi. Nama Ibrani Yōḥānān, yang disandang John the Baptist dan John the Apostle, masuk ke bahasa Yunani sebagai Iōánnēs dan Latin sebagai Iohannes, lalu menyebar ke seluruh dunia Kristen. Eropa Barat mempertahankan bunyi awal J/G (John, Jean, Juan, Giovanni); dunia Slavia Timur mengubahnya menjadi Ivan; dan Qurʼan melestarikan bentuk Arab yang sejajar, Yaḥyā, untuk nabi yang sama."},"mary":{"id":"Nama ibu Yesus dan Miriam, saudari Musa, dan melalui mereka menjadi salah satu nama perempuan yang paling dihormati di dunia. Maria dalam bahasa Yunani dan Latin menyebarkannya ke setiap bahasa Kristen; Qurʼan menyebutnya Maryam, satu-satunya perempuan yang disebut namanya di dalamnya, sehingga nama ini sama pentingnya di dunia Islam."},"muhammad":{"id":"Nama Nabi Islam, dan menurut banyak perhitungan merupakan nama laki-laki yang paling umum di Bumi. Dari bahasa Arab muḥammad (akar ḥ-m-d, “memuji”), nama ini menyebar bersama Islam ke setiap bahasa dunia Muslim, masing-masing mengubah bunyinya: Mehmet dalam bahasa Turki, Mohammad dalam bahasa Persia/Urdu, Muhamed di Bosnia, Mamadou di Afrika Barat, Muhammad/Mohd di Asia Tenggara."},"alexander":{"id":"Dibawa melintasi tiga benua oleh Alexander Agung, yang penaklukannya menanamkan nama ini dari Yunani hingga India. Kemudian Kekristenan menyebarkannya lebih jauh melalui para santo dan paus. Hampir di mana-mana nama ini disingkat secara akrab — Alex, Sasha, Sander, Xander, Ale, Iskandar — dan bahkan masuk ke dunia Islam sebagai Iskandar/Sikandar."},"joseph":{"id":"Nama sang leluhur Joseph, yang dijual ke Mesir, dan Santo Joseph, suami Mary. Bahasa Ibrani Yōsēf melewati bahasa Yunani Iōsḗph dan Latin Ioseph masuk ke setiap bahasa Kristen, memendek menjadi José di Iberia, Giuseppe di Italia, dan Josef di dunia Jerman dan Slavia. Qurʼan menuturkan kisah leluhur yang sama dalam bentuk Arab yang sejajar, Yūsuf, yang menyebar bersama Islam dari Afrika Barat hingga Indonesia."},"michael":{"id":"Semula merupakan nama malaikat agung Michael, panglima prajurit bala tentara surga, yang pemujaannya membawa nama ini ke seluruh dunia Kristen. Michaḗl dalam bahasa Yunani dan Michael dalam bahasa Latin bercabang menjadi Michel, Miguel, Michele, Michael, dan Mikhail dalam bahasa Slavia, melunakkan bunyi tenggorokan Ibrani ḵ menjadi bunyi k atau h di sepanjang jalan. Al-Qurʼan menyebut malaikat yang sama dengan nama Mīkāʼīl, menghadirkan bentuk Islam yang sejajar dan dipakai dari Iran hingga Afrika Barat."},"george":{"id":"Dari bahasa Yunani Geōrgios, dibangun atas geōrgós “petani, penggarap tanah”, nama ini memiliki jangkauan yang begitu luas berkat Saint George, martir penakluk naga yang dihormati di seluruh dunia Kristen dan santo pelindung Inggris, Georgia, dan Etiopia. Nama ini menyebar menjadi Jorge, Giorgio, Georg, dan Jerzy, sedangkan dunia Slavia Timur memecahnya menjadi dua nama yang sama-sama hidup — Georgy yang terpelajar dan Yuri yang sehari-hari. Di Kaukasus ia menjadi nama kesayangan seluruh bangsa: Giorgi dalam bahasa Georgia dan Gevorg dalam bahasa Armenia."},"sophia":{"id":"Dalam bahasa Yunani, sophía berarti sekadar “kebijaksanaan”, dipersonifikasikan sebagai sebuah keutamaan dan diabadikan dalam gereja agung Hagia Sophia di Konstantinopel, “Kebijaksanaan Suci”. Diusung melalui tradisi Bizantium dan Ortodoks serta disandang oleh para maharani dan orang kudus, nama ini menyebar menjadi Sofia, Sophie, Zsófia, dan Zofia. Kini ia menjadi salah satu nama anak perempuan terpopuler di dunia, memuncaki daftar kelahiran di seantero Eropa dan Amerika; bahasa Rusia memberinya bentuk sayang yang lembut, Sonya."},"fatima":{"id":"Nama Fāṭima al-Zahrāʼ, putri Nabi Muhammad dan istri ʿAlī, sehingga menjadi salah satu nama perempuan yang paling dimuliakan dalam Islam — terutama dalam tradisi Syiah, yang menganggapnya ibu para imam. Dari akar kata Arab f-ṭ-m (“menyapih”), nama ini menyebar bersama Islam dan melunak di sepanjang jalan: bahasa Turki memangkasnya menjadi Fatma, bahasa Persia membulatkan akhirannya menjadi Fāṭeme, sedangkan Asia Selatan dan Asia Tenggara mempertahankan bentuk yang lebih penuh, Fatimah. Di Balkan ia hidup terus sebagai Fatima dengan bentuk sayang Fata."},"ali":{"id":"Nama ʿAlī ibn Abī Ṭālib, sepupu sekaligus menantu Nabi Muhammad, khalifah keempat dalam tradisi Sunni dan imam pertama Islam Syiah — yang menjadikan Ali salah satu nama sentral dunia Muslim, sekaligus salah satu “nama-nama yang indah”, sebab al-ʿAlī adalah salah satu sifat Allah. Dari bahasa Arab ʿAlī (akar ʿ-l-w, “menjadi tinggi”), bunyinya berpindah antarbahasa nyaris tanpa perubahan: Ali dalam bahasa Turki dan Persia, Ali dalam bahasa Urdu, Alija dalam bahasa Bosnia, Aliyu di Afrika Barat. Di Barat ia paling dikenal lewat petinju Muhammad Ali."},"krishna":{"id":"Krishna adalah awatara kedelapan Vishnu dan salah satu dewa yang paling dicintai dalam Hindu — sang penggembala sapi peniup seruling dari Vrindavan sekaligus sais kereta yang bijaksana dalam Bhagavad Gita. Kata Sanskerta kṛṣṇa secara harfiah berarti “gelap, hitam”, menggambarkan warna kulitnya, dan melahirkan bentuk-bentuk sayang seperti Kanha serta Kannan dalam bahasa Tamil. Sebagai nama diri, ia umum di seluruh India dan di segenap diaspora Hindu; penyebarannya di Asia Tenggara berlangsung lewat teater bayangan wayang dan Mahabharata."},"rama":{"id":"Rama adalah awatara Vishnu dan pahlawan wiracarita Ramayana, raja ideal Ayodhya yang kisahnya termasuk paling sering dikisahkan ulang di dunia. Kata Sanskerta rāma berarti “menyenangkan, memikat”. Yang terutama, justru wiracarita inilah yang membawa nama itu ke seantero Asia Tenggara: para raja Thai dari wangsa Chakri semuanya bergelar Rama, Ayutthaya sendiri dinamai menurut Ayodhya tempat kelahiran Rama, dan Rama tetap hidup dalam Reamker Kamboja (sebagai Preah Ream), wayang Jawa dan Bali, serta Phra Lak Phra Ram dari Laos."},"david":{"id":"Nama raja gembala Israel, raja kedua dan penakluk Goliat, yang dihormati dalam Yudaisme, Kristen, maupun Islam sama besarnya. Kata Ibrani Dāwīḏ melewati bahasa Yunani dan Latin masuk ke setiap bahasa Eropa nyaris tanpa perubahan, sementara Davit dari Georgia dan Dawit dari Etiopia menjadi nama raja tersendiri. Karena Daud juga seorang nabi dalam Al-Qurʼan, sebuah garis Islam yang sejajar mengalir melalui bentuk Arab Dāwūd — Daud, Davut, Daudi — di seluruh dunia Muslim."},"daniel":{"id":"Berasal dari nabi pelihat dalam Kitab Daniel, yang imannya di gua singa menjadikan nama ini kiasan bagi keteguhan. Kata Ibrani Dāniyyēl mengembara lewat Yunani Daniḗl dan Latin Daniel ke Dunia Barat Kristen, dengan ejaan yang tetap mengagumkan stabilnya, sementara dunia Slavia membentuknya kembali menjadi Daniil dan Danylo. Daniel juga dihormati dalam tradisi Islam sebagai nabi Dāniyāl, yang makamnya di Susa tetap menjadi tempat ziarah."},"peter":{"id":"Nama yang diberikan Yesus kepada nelayan Simon — bahasa Yunani Pétros, \"batu karang\", terjemahan dari julukan Aram Kēfā — menjadikannya batu karang tempat Gereja dibangun. Sebagai paus pertama, Santo Petrus membawa nama itu ke setiap negeri Kristen: Latin Petrus, Prancis Pierre, Spanyol Pedro, Italia Pietro, Rusia Pyotr. Umat Kristen Timur mempertahankan bentuk Yunani Petros, dan umat Kristen berbahasa Arab menyebutnya Buṭrus."},"paul":{"id":"Kognomen Romawi Paulus, “kecil”, yang disandang oleh Rasul Paul — yang lahir sebagai Saul dari Tarsus — dan surat-suratnya membentuk teologi Kristen serta membawa namanya ke seluruh dunia. Gereja-gereja berbahasa Yunani mengenalnya sebagai Paûlos, dan dari Paulus dalam bahasa Latin muncullah Pablo, Paolo, Paulo, Paweł serta Pavel dalam bahasa Slavia. Bahasa Armenia mengubahnya secara mencolok menjadi Poġos, dan umat Kristen berbahasa Arab menyebutnya Būlus."},"thomas":{"id":"Julukan sang rasul yang meragukan Kebangkitan hingga ia menyentuh luka-luka Kristus — bahasa Aram Tʼōmā, “kembar”, yang dalam Injil Yunani juga diterjemahkan sebagai Dídymos. Melalui Thōmâs dalam bahasa Yunani dan Thomas dalam bahasa Latin, nama ini menyebar ke barat sebagai Thomas, Tomás, Tommaso, dan Tomasz, sementara dunia Slavia timur mengubahnya menjadi Foma dan Khoma. Umat Kristen berbahasa Arab mempertahankan bunyi Aram itu sebagai Tūmā."},"abraham":{"id":"Bapa bangsa yang dihormati sebagai bapa kaum beriman dalam ketiga agama Abrahamik. Nama Ibrani Avraham, “bapa banyak bangsa”, melewati Abraám dalam bahasa Yunani dan Abraham dalam bahasa Latin menuju Barat Kristen, sementara Al-Qurʼan memberikan bentuk sejajar Ibrāhīm — salah satu nama laki-laki paling umum di seluruh dunia Muslim, dari Maroko hingga Indonesia. Bahasa Belanda memendekkannya menjadi Bram; kawasan Kaukasus mengubahnya menjadi Ibragim."},"isaac":{"id":"Putra Abraham dan bapa bangsa kedua, nama Ibraninya Yitzḥaq berarti “ia tertawa.” Isaák dalam bahasa Yunani dan Isaac dalam bahasa Latin membawanya ke barat — Isacco dalam bahasa Italia, Isaak dalam bahasa Jerman dan Rusia — sementara Al-Qurʼan menyebut nabi yang sama dengan nama Isḥāq. Menjadi favorit di kalangan keluarga Yahudi, Kristen, maupun Muslim, nama ini disandang oleh tokoh-tokoh mulai dari Isaac Newton hingga penulis Rusia Isaak Babel."},"jacob":{"id":"Bapa bangsa ketiga, yang kemudian diganti namanya menjadi Israel; nama Ibraninya Yaʿaqov melahirkan salah satu pohon keluarga paling ruwet dalam seluruh ilmu onomastika. Iacobus dalam bahasa Latin menghasilkan Jacob, Jakob, dan Yakov dalam bahasa Slavia, tetapi varian Latin Vulgar Iacomus memisahkan diri menjadi Giacomo dalam bahasa Italia, Jacques dalam bahasa Prancis, James dalam bahasa Inggris, serta Diego, Santiago, Tiago, dan Jaime di Iberia — semuanya adalah bentuk kembar dari nama yang sama persis. Al-Qurʼan melestarikan nabi ini sebagai Yaʻqūb."},"moses":{"id":"Nabi yang memimpin bangsa Israel keluar dari Mesir; nama Ibraninya, Mosheh, secara tradisional dimaknai \"yang ditarik keluar dari air.\" Melalui bahasa Yunani Mōÿsês dan Latin Moyses, nama ini menyebar sebagai Moses, Moïse dalam bahasa Prancis, Moisés dalam bahasa Spanyol, dan Mosè dalam bahasa Italia; sementara Mūsā — yang disebut dalam Al-Qurʼan lebih sering daripada nabi mana pun — menjadi salah satu nama besar dunia Muslim, yang disandang kaisar Mali, Mansa Musa."},"solomon":{"id":"Raja bijaksana, putra David; nama Ibraninya, Shlomoh, berasal dari shalom, \"damai.\" Melalui bahasa Yunani Solomṓn dan Latin Salomon lahir Solomon, lalu Salomon dalam bahasa Prancis, Salomone dalam bahasa Italia, dan Salomão dalam bahasa Portugis. Para kaisar Ethiopia mengaku sebagai keturunannya melalui dinasti Solomon, dan Al-Qurʼan memuliakannya sebagai nabi sekaligus raja Sulaymān — asal usul nama Turki Süleyman, yang disandang sultan Utsmaniyah terbesar."},"matthew":{"id":"Nama rasul dan penginjil Matthew, pemungut cukai yang dipanggil oleh Yesus dan menurut tradisi penulis Injil pertama. Bahasa Ibrani Mattityāhū (\"karunia Yahweh\") dipendekkan dalam bahasa Yunani menjadi Maththaîos dan di-Latinkan sebagai Matthaeus, lalu menyebar ke seluruh dunia Kristen sebagai Matteo, Mateo, Matthieu, Mateusz, dan Matvei dalam bahasa Slavia. Umat Kristen berbahasa Arab mengenal sang penginjil sebagai Mattā."},"adam":{"id":"Nama manusia pertama, yang dibentuk dari tanah dalam Kitab Kejadian dan disebut dua puluh lima kali dalam Al-Qurʼan, sehingga dimiliki bersama oleh orang Yahudi, Kristen, dan Muslim. Uniknya, nama ini nyaris tak berubah bentuk saat berpindah dari satu bahasa ke bahasa lain — Adam dalam bahasa Inggris, Jerman, Polandia, dan Arab, Adán dalam bahasa Spanyol, Adamo dalam bahasa Italia, Adem dalam bahasa Turki dan Bosnia, Adamu dalam bahasa Hausa dan Swahili. Di dunia Islam, Ādam sangat lazim sebagai nama sehari-hari."},"noah":{"id":"Pembangun bahtera yang selamat dari Air Bah, dimuliakan baik dalam Alkitab maupun Al-Qurʼan. Bahasa Ibrani Nōaḥ melewati bahasa Yunani Nôe dan Latin Noe menjadi Noé dalam rumpun Roman dan Noè dalam bahasa Italia, sementara bahasa Inggris mempertahankan bentuk yang lebih penuh, Noah. Pada abad kedua puluh satu, Noah melonjak ke puncak daftar nama anak laki-laki di seluruh Amerika Serikat dan Eropa, bahkan dipinjam kembali ke Jepang sebagai nama modern Noa. Al-Qurʼan mengisahkan cerita yang sama dalam bentuk Arab paralel Nūḥ, salah satu dari lima nabi terbesar Islam."},"gabriel":{"id":"Nama malaikat agung yang menyingkapkan penglihatan kepada Daniel, mengabarkan kelahiran John dan Jesus, dan dalam Islam mendiktekan Qurʼan kepada Muhammad. Gaḇrīʼēl dari bahasa Ibrani menjadi Gabriḗl dalam bahasa Yunani dan Gabriel dalam bahasa Latin, tetap dekat dengan asalnya dalam bahasa Prancis, Spanyol, Portugis, dan Jerman, melembut menjadi Gabriele dalam bahasa Italia serta Gavriil / Gavrilo dalam bahasa Slavia. Qurʼan menyebut malaikat yang sama dengan nama Jibrīl, dan di Ethiopia malaikat agung Gabrʼel sangat dihormati."},"elijah":{"id":"Nama nabi berapi-api dari abad ke-9 SM yang menantang para imam Baal di Gunung Carmel dan diangkat ke surga dalam angin puyuh. Dalam bahasa Yunani Perjanjian Baru ia disebut Ēlías, yang melahirkan Elias dalam bahasa Latin serta berbagai bentuk Eropa Elias / Élie / Ilie, sementara dunia Slavia Timur menjadikannya Ilya sehari-hari. Bentuk yang lebih lengkap, Elijah, telah menjadi salah satu nama paling populer dalam bahasa Inggris modern. Qurʼan menghormati nabi yang sama dalam bentuk Arab paralel Ilyās."},"sarah":{"id":"Nama istri sang patriark Abraham, yang dalam Kitab Kejadian namanya diubah dari Sarai menjadi Sarah, \"sang putri\". Sárra dalam bahasa Yunani dan Sara dalam bahasa Latin membawanya ke seluruh dunia Kristen, tempat ia menjadi salah satu nama perempuan paling populer pada era modern. Karena Abraham adalah patriark bersama, nama yang sama tetap hidup di dunia Muslim sebagai Sāra, dan bervariasi secara penuh kasih dari Zara hingga Saara dalam bahasa Finlandia."},"anna":{"id":"Berasal dari bahasa Ibrani Ḥannāh, ibu nabi Samuel, yang namanya berarti \"anugerah\". Bahasa Yunani menuliskannya Ánna — disandang oleh nabiah Anna dalam Injil Lukas — dan melalui bahasa Latin menjadi salah satu nama perempuan paling tersebar luas di Eropa, semakin dihormati sebagai nama Santa Anne, ibu Perawan Mary. Bahasa Inggris melestarikan baik Anna yang berasal dari Yunani maupun Hannah yang dipulihkan dari Ibrani sebagai sepasang kata kembar, dan tokoh yang sama muncul dalam Islam sebagai Ḥanna, ibu Mary."},"elizabeth":{"id":"Berasal dari bahasa Ibrani Elišévaʿ, istri Aaron dan, dalam Injil Lukas, ibu John the Baptist. Elisábet dalam bahasa Yunani dan Elisabeth dalam bahasa Latin menyebarkannya ke seluruh dunia Kristen, tempat ia disandang oleh para santo dan deretan panjang para ratu, terutama Elizabeth I dan Elizabeth II dari Inggris. Di Semenanjung Iberia, nama yang sama dibentuk ulang menjadi cabang terkenal, Isabel (Italia Isabella), sementara dunia Slavia dan Hungaria memberinya bentuk Yelizaveta dan Erzsébet."},"omar":{"id":"Disandang oleh ʿUmar ibn al-Khattāb, sahabat Nabi dan khalifah Rāshidūn kedua yang masa pemerintahannya membentuk negara Islam awal, ʿUmar adalah salah satu nama laki-laki klasik dunia Muslim. Dari akar kata Arab ʿ-m-r (“hidup, berkembang”), namanya berarti “berumur panjang, makmur”. Nama ini berubah menjadi Ömer dalam bahasa Turki dan Omer dalam bahasa Bosnia, serta dikenal di Barat melalui tokoh seperti Omar Sharif. Nama Ibrani Omar yang tidak berkaitan — cucu Esau dalam Kitab Kejadian — hanyalah kebetulan kesamaan bunyi."},"aisha":{"id":"Nama ʿĀʼisha bint Abī Bakr, seorang istri Nabi Muhammad yang termasyhur sebagai cendekiawan dan periwayat hadis, yang menjadikannya salah satu nama perempuan paling populer di seluruh dunia Muslim. Dari akar kata Arab ʿ-y-sh (“hidup”), namanya berarti “yang hidup”. Bahasa Turki mengubahnya menjadi Ayşe — lama menjadi nama perempuan paling umum di Turki — sementara di Maghrib dipakai Aïcha dan di Asia Selatan Ayesha. Dalam beberapa dekade terakhir, nama ini juga populer luas di Inggris, Prancis, dan Amerika Serikat."},"khadija":{"id":"Khadīja bint Khuwaylid adalah istri pertama Nabi Muhammad, seorang saudagar Makkah yang kaya dan orang pertama yang menerima Islam; namanya dihargai sejak saat itu. Nama ini berasal dari akar kata Arab kh-d-j, yang berkaitan dengan anak yang “lahir dini” atau prematur. Bahasa Turki membawanya sebagai Hatice, Afrika Barat sebagai Hadiza dalam bahasa Hausa dan Khady di Senegal, serta bahasa Swahili sebagai Hadija. Bersama Fatima dan Aisha, ia termasuk nama perempuan yang paling umum di dunia Muslim."},"abdullah":{"id":"Nama teoforik yang berarti “hamba Allah”, terbentuk dari ʿabd (“hamba”) dan Allāh. Ini adalah nama ayah Nabi Muhammad, ʿAbd Allāh ibn ʿAbd al-Muttalib, dan sebuah hadis menyebut ʿAbdullāh dan ʿAbd al-Rahmān sebagai nama yang paling dicintai Allah — sehingga termasuk nama yang paling dianjurkan dalam Islam. Nama ini tersebar di dunia Muslim dengan perubahan bunyi yang ringan: Abdollah dalam bahasa Persia, Abdallah dan Abdellah di Maghrib, Abdullahi di Nigeria, Abdoulaye di Afrika Barat berbahasa Prancis, dan Abdulah di Bosnia."},"hassan":{"id":"Ḥasan (akar kata ḥ-s-n, “baik, indah”) adalah nama Hasan ibn Ali, cucu tertua Nabi Muhammad dan Imam Syiah kedua. Nama ini hampir selalu dipasangkan dengan nama adiknya — Hasan dan Husayn bersama-sama. Dibawa Islam ke seluruh dunia, ia mempertahankan bentuk yang luar biasa stabil (Hasan dalam bahasa Turki, Hasan/Haso dalam bahasa Bosnia) dan tetap menjadi salah satu nama laki-laki yang paling umum di dunia Muslim."},"husayn":{"id":"Ḥusayn adalah bentuk diminutif dari Ḥasan — \"Hasan kecil\", \"si mungil yang elok\". Nama ini disandang oleh Husayn ibn Ali, cucu bungsu Nabi, yang kesyahidannya dalam Pertempuran Karbala pada 680 M menjadikan nama ini jantung emosional Islam Syiah, yang diperingati setiap tahun pada Asyura. Ragam bentuknya mengelilingi dunia Muslim: Hossein dalam bahasa Persia, Hüseyin dalam bahasa Turki, Hussain di Asia Selatan, dan Hussein dalam bahasa Arab yang disandang Saddam Hussein serta Raja Hussein dari Yordania."},"zaynab":{"id":"Zaynab adalah nama sejenis tumbuhan gurun yang harum dan berbunga. Nama ini disandang oleh salah seorang putri Nabi Muhammad, Zaynab bint Muhammad, dan oleh cucunya, Zaynab bint Ali, saudari Husayn dan pahlawan wanita yang dihormati dalam tragedi Karbala. Nama ini berkembang di seluruh dunia Muslim, terutama sebagai Zeynep dalam bahasa Turki — selama bertahun-tahun nama anak perempuan paling populer di Turki — dan sebagai Zenabou di Afrika Barat."},"nicholas":{"id":"Berasal dari bahasa Yunani Nikólaos, \"kemenangan rakyat\", disebarkan ke seluruh dunia Kristen melalui pemujaan Santo Nicholas dari Myra — uskup abad ke-4 yang legenda pemberian hadiahnya menjelma menjadi Santa Claus, nama yang sendirinya luntur dari bahasa Belanda Sinterklaas. Hampir di mana-mana nama ini dipendekkan secara akrab: Klaus dalam bahasa Jerman, Klaas dalam bahasa Belanda, Nikos dalam bahasa Yunani, Kolya dalam bahasa Rusia. Eropa Timur membentuknya menjadi Nikolai, Mykola, dan Mikuláš, sementara Hungaria menjadikannya Miklós."},"helen":{"id":"Bentuk Inggris dari Helénē dalam bahasa Yunani, kemungkinan berasal dari kata yang berarti \"obor\" atau \"yang bercahaya\". Nama ini disandang oleh Helen dari Troya, yang kecantikannya konon telah \"melayarkan seribu kapal\", dan oleh Santa Helena, ibu Kaisar Constantine, yang dianggap menemukan Salib Sejati. Melalui bahasa Latin Helena, nama ini menjadi Elena di seluruh dunia Roman dan Slavia selatan, serta Yelena / Olena di timur, sementara bahasa Hungaria membentuknya menjadi Ilona."},"catherine":{"id":"Berasal dari bahasa Yunani Aikaterínē, sejak awal dikaitkan lewat etimologi rakyat dengan katharós, \"murni\", yang memantapkan ejaan -th- di Barat. Disebarkan oleh pemujaan yang teramat populer terhadap Santa Catherine dari Aleksandria, nama ini menjadi salah satu nama perempuan yang paling banyak dipakai di Eropa, disandang oleh para ratu dan permaisuri dari Catherine de Medici hingga Catherine the Great. Nama ini dipendekkan menjadi seperangkat nama sayang — Kate, Katie, Katya, Kasia — salah satunya, Karin dalam bahasa Jerman dan Swedia, homofon dengan sebuah nama anak perempuan Jepang."},"margaret":{"id":"Berasal dari bahasa Yunani margarítēs (\"mutiara\"), kata yang bahasa Yunani sendiri pinjam dari wilayah lebih jauh ke timur. Pemujaan terhadap Santa Margaret dari Antiokhia menjadikannya favorit di seluruh Eropa abad pertengahan, kemudian disandang oleh para ratu dan tokoh dari Margaret Thatcher hingga Margaret Atwood. Bentuk-bentuk sayangnya berkembang sendiri — Greta dalam bahasa Jerman, Rita dalam bahasa Italia dan Spanyol, serta Daisy dalam bahasa Inggris, karena kata Prancis marguerite kemudian menjadi nama bunga aster itu."},"philip":{"id":"Berasal dari bahasa Yunani Phílippos (\"pencinta kuda\"), nama bangsawan Makedonia yang disandang Philip II, ayah Alexander Agung. Sebagai nama seorang rasul, nama ini menyebar ke seluruh dunia Kristen, dan menjadi favorit para raja Iberia — enam Felipe Spanyol dan beberapa Filipe Portugis, yang menjadi asal nama Filipina (Philippines). Orang Britania paling mengenalnya melalui Prince Philip, mendiang Adipati Edinburgh."},"theodore":{"id":"Berasal dari bahasa Yunani Theódōros (\"karunia Tuhan\"), cerminan terbalik dari Dorothea. Disandang banyak santo mula-mula, nama ini berakar di seluruh Eropa dan sekitarnya — Fyodor bahasa Rusia milik Dostoevsky dan Tewodros dari Etiopia. Dalam bahasa Inggris, ia memikat lewat bentuk sayang Ted, Teddy, dan Theo."},"anthony":{"id":"Berasal dari nama keluarga Romawi Antōnius, sebuah gens kuno yang mungkin berasal Etruska dan anggotanya yang paling terkenal adalah Mark Antony (Marcus Antōnius). Banyak santo bernama Anthony — terutama Anthony Agung dan Anthony dari Padua — membawanya ke seluruh dunia Kristen, tempat Antonio menjadi salah satu nama tersering di Italia dan Iberia. Ejaan dengan huruf h mencerminkan kaitan keliru di kemudian hari dengan kata Yunani ánthos (\"bunga\")."},"julia":{"id":"Bentuk feminin dari nama gens Romawi Iūlius, keluarga Julius Caesar dan Kaisar Augustus, yang menjadikan Iūlia salah satu nama besar wangsa Julio-Claudius — baik putri Caesar maupun putri Augustus bernama Julia. Sejak lama juga menjadi nama seorang santa Kristen, kini ia salah satu nama anak perempuan terpopuler di seluruh Eropa dan benua Amerika. Padanan maskulinnya tetap hidup sebagai Julius, Julio, dan Jules."},"lakshmi":{"id":"Lakshmi adalah dewi Hindu kekayaan, keberuntungan, dan kecantikan, sekaligus pasangan Vishnu yang muncul dalam wujud yang padan di samping setiap awatara-nya. Kata Sanskerta lakṣmī berasal dari lakṣ “menandai, mencerap”, sehingga bermakna pertanda baik dan, secara meluas, kemakmuran. Ia dipuja terutama saat Diwali, dan namanya termasuk salah satu nama perempuan yang paling umum di seantero India Selatan — meski nama gabungan seperti Lakshmi Narayan dan marga seperti Mittal juga menyandangnya untuk laki-laki. Di Bengal, sang dewi maupun namanya dilafalkan Lokkhi."},"arjun":{"id":"Arjuna adalah pahlawan pemanah dalam Mahabharata — yang ketiga di antara lima bersaudara Pandawa, putra dewa Indra, dan kesatria yang kepadanya Krishna menyampaikan Bhagavad Gita di medan perang Kurukshetra. Kata Sanskerta arjuna berarti “terang, perak, putih”. Dalam bentuk Arjun, nama ini termasuk salah satu nama anak laki-laki yang paling populer di India masa kini, dan wiracarita itu membawa sosoknya ke seantero Asia Tenggara, tempat sang ksatriya Arjuna yang halus budi (dalam bahasa Jawa Janaka) menjadi tokoh favorit dalam teater bayangan wayang."},"sita":{"id":"Sita adalah tokoh utama perempuan dalam Ramayana dan istri Rama, sebuah awatara Lakshmi sekaligus lambang keutamaan, kesetiaan, dan keteguhan yang sempurna. Nama Sanskertanya berarti “alur bajak”: ia ditemukan Raja Janaka di sebuah ladang yang baru dibajak, putri dewi bumi Bhumi. Wiracarita itu menyebarkannya ke seantero Asia Tenggara — ia adalah Nang Sida (นางสีดา) dalam Ramakien Thailand, Sinta atau Shinta dalam wayang Jawa, dan Neang Seda dalam Reamker Kamboja."},"ganesh":{"id":"Ganesha adalah putra berkepala gajah dari Shiva dan Parvati, dewa tercinta penyingkir rintangan sekaligus pelindung segala permulaan, pembelajaran, dan kesenian, yang dimohoni sebelum setiap usaha baru. Nama Sanskertanya memadukan gaṇa “rombongan, pasukan” dengan īśa “tuan”, dan ia juga dikenal sebagai Vinayaka dan Ganapati. Dalam bentuk Ganesh, ini adalah nama anak laki-laki yang lazim di India, dan sang dewa menyebar ke seantero Asia Tenggara — dipuja di Thailand sebagai Phra Phikhanet (พระพิฆเนศ), pelindung kesenian, dan di Indonesia sebagai Ganesha, yang citranya menjadi lambang Institut Teknologi Bandung (ITB)."},"priya":{"id":"Priya semata-mata sebuah nama diri, bukan dewa — bentuk feminin dari kata Sanskerta priya “terkasih, tercinta”, dari akar prī “menyenangkan”. Ia termasuk salah satu nama perempuan yang paling umum masa kini di seantero India, Nepal, Bangladesh, dan Sri Lanka, dan mudah merambah ke diaspora sebagai bentuk yang ramah dan gampang dilafalkan. Dalam bahasa Tamil, bentuk maskulin Priyan atau Priya juga dipakai untuk laki-laki. Akar kata ini kuno: ia sekerabat dengan nama dewi Jermanik Frigg, keduanya berasal dari Proto-Indo-Eropa *priH- “terkasih”."}};
